// Test HTML generated by the UI + backend communications without a GUI browser.
const fs=require('fs'),vm=require('vm'),assert=require('assert');
const src=fs.readFileSync(__dirname+'/shared.js','utf8');
let cookie='';
async function fetchLocal(path, opts={}) {
 const headers={...(opts.headers||{})};if(cookie)headers.Cookie=cookie;
 const response=await fetch('http://127.0.0.1:8896'+path,{...opts,headers});
 const set=response.headers.get('set-cookie');
 if(set){const m=set.match(/dakhla_session=([^;]*)/);if(m)cookie=m[1]?`dakhla_session=${m[1]}`:'';}
 return response;
}
function appPage(){
 const elements={};const nav=[];
 const document={body:{dataset:{page:'app'}},getElementById(id){return elements[id]||(elements[id]={id,innerHTML:'',value:'',hidden:false,textContent:'',scrollTop:0,scrollHeight:999,scrollIntoView(){},focus(){}})}};
 const win={location:{assign(x){nav.push(x)},replace(x){nav.push(x)}},scrollTo(){}};
 const ctx={console,document,window:win,fetch:fetchLocal,alert(){},confirm(){return true}};
 vm.createContext(ctx);vm.runInContext(src,ctx);return {ctx,elements,nav};
}
const wait=(ms=140)=>new Promise(r=>setTimeout(r,ms));
(async()=>{
 let res=await fetchLocal('/api/session');let csrf=(await res.json()).csrf;
 res=await fetchLocal('/api/login',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrf},body:JSON.stringify({email:'client@demo.test',password:'Demo2026!'})});assert(res.ok);
 let page=appPage();await wait();
 await page.ctx.openMessages(1001,'p1');
 assert(page.elements.workspace.innerHTML.includes('Mes conversations'));
 assert(page.elements.workspace.innerHTML.includes('Artisan démo A'));
 assert(page.elements.workspace.innerHTML.includes('chat-composer'));
 page.ctx.document.getElementById('chat-input').value='Bonjour, avez-vous un créneau samedi ?';
 await page.ctx.sendChatMessage({preventDefault(){},target:{querySelector(){return {disabled:false}}}});
 const messages=vm.runInContext('threadMessages',page.ctx);
 assert(messages.some(m=>m.body.includes('créneau samedi')));
 assert(page.elements['chat-scroll'].innerHTML.includes('Bonjour, avez-vous un créneau samedi ?'));
 await page.ctx.logoutDemo();
 res=await fetchLocal('/api/session');csrf=(await res.json()).csrf;
 res=await fetchLocal('/api/login',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrf},body:JSON.stringify({email:'pro@demo.test',password:'Demo2026!'})});assert(res.ok);
 page=appPage();await wait();
 await page.ctx.openMessages(1001,'p1');
 assert(page.elements.workspace.innerHTML.includes('Client Démo'));
 assert(page.elements.workspace.innerHTML.includes('Bonjour, avez-vous un créneau samedi ?'));
 console.log('PASS V6 JS : la messagerie s’ouvre et se synchronise entre client et prestataire.');
})().catch(e=>{console.error(e);process.exitCode=1});
